+      :root {
+        color-scheme: light;
+        --bg: #f4f7fb;
+        --surface: rgba(255, 255, 255, 0.9);
+        --surface-strong: #ffffff;
+        --text: #16202d;
+        --muted: #5a6778;
+        --border: #d6deea;
+        --accent: #3b82f6;
+        --accent-soft: #eaf2ff;
+        --shadow: 0 18px 50px rgba(20, 33, 61, 0.12);
+        --radius: 24px;
+      }
+
+      * {
+        box-sizing: border-box;
+      }
+
+      html {
+        scroll-behavior: smooth;
+      }
+
+      body {
+        margin: 0;
+        font: 16px/1.6 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
+          sans-serif;
+        color: var(--text);
+        background:
+          radial-gradient(circle at top, rgba(59, 130, 246, 0.14), transparent 36%),
+          linear-gradient(180deg, #eef4fb 0%, var(--bg) 100%);
+      }
+
+      a {
+        color: inherit;
+      }
+
+      .skip-link {
+        position: absolute;
+        left: 1rem;
+        top: 1rem;
+        transform: translateY(-200%);
+        padding: 0.75rem 1rem;
+        border-radius: 999px;
+        background: var(--surface-strong);
+        color: var(--text);
+        border: 1px solid var(--border);
+        box-shadow: var(--shadow);
+        z-index: 1000;
+      }
+
+      .skip-link:focus {
+        transform: translateY(0);
+      }
+
+      main {
+        width: min(100% - 2rem, 920px);
+        margin: 0 auto;
+        padding: 5.5rem 0 4rem;
+      }
+
+      .hero {
+        display: grid;
+        gap: 1rem;
+        padding: 1.5rem;
+        margin-bottom: 1.5rem;
+        border: 1px solid var(--border);
+        border-radius: var(--radius);
+        background: var(--surface);
+        backdrop-filter: blur(14px);
+        box-shadow: var(--shadow);
+      }
+
+      .eyebrow {
+        display: inline-flex;
+        width: fit-content;
+        align-items: center;
+        gap: 0.5rem;
+        padding: 0.35rem 0.75rem;
+        border-radius: 999px;
+        background: var(--accent-soft);
+        color: #1d4ed8;
+        font-size: 0.875rem;
+        font-weight: 700;
+        letter-spacing: 0.02em;
+      }
+
+      h1 {
+        margin: 0;
+        font-size: clamp(2rem, 5vw, 3.5rem);
+        line-height: 1.05;
+        letter-spacing: -0.04em;
+      }
+
+      .lede {
+        max-width: 62ch;
+        margin: 0;
+        color: var(--muted);
+        font-size: 1.05rem;
+      }
+
+      .faq-list {
+        display: grid;
+        gap: 1rem;
+      }
+
+      .example {
+        padding: 0;
+      }
+
+      details {
+        border: 1px solid var(--border);
+        border-radius: 20px;
+        background: var(--surface-strong);
+        box-shadow: 0 10px 30px rgba(20, 33, 61, 0.06);
+        overflow: clip;
+      }
+
+      summary {
+        list-style: none;
+        cursor: pointer;
+        display: flex;
+        align-items: center;
+        justify-content: space-between;
+        gap: 1rem;
+        padding: 1.1rem 1.2rem;
+        font-weight: 700;
+        font-size: 1.03rem;
+        outline: none;
+      }
+
+      summary::-webkit-details-marker {
+        display: none;
+      }
+
+      summary::after {
+        content: "+";
+        flex: none;
+        width: 2rem;
+        height: 2rem;
+        display: grid;
+        place-items: center;
+        border-radius: 999px;
+        background: var(--accent-soft);
+        color: #1d4ed8;
+        font-size: 1.2rem;
+        line-height: 1;
+        transition: transform 160ms ease, background-color 160ms ease;
+      }
+
+      details[open] summary::after {
+        content: "–";
+        transform: rotate(0deg);
+        background: #dbeafe;
+      }
+
+      summary:hover {
+        background: #f8fbff;
+      }
+
+      summary:focus-visible {
+        box-shadow: inset 0 0 0 3px var(--accent);
+      }
+
+      .details {
+        padding: 0 1.2rem 1.2rem;
+        color: var(--muted);
+      }
+
+      .details p {
+        margin: 0;
+      }
+
+      .details p + p {
+        margin-top: 0.75rem;
+      }
+
+      .footer-note {
+        margin-top: 1.5rem;
+        color: var(--muted);
+        font-size: 0.95rem;
+      }
+
+      @media (max-width: 640px) {
+        main {
+          width: min(100% - 1rem, 920px);
+          padding-top: 4.75rem;
+        }
+
+        .hero,
+        summary,
+        .details {
+          padding-left: 1rem;
+          padding-right: 1rem;
+        }
+      }
+
+      @media (prefers-reduced-motion: reduce) {
+        html {
+          scroll-behavior: auto;
+        }
+
+        *,
+        *::before,
+        *::after {
+          animation-duration: 0.01ms !important;
+          animation-iteration-count: 1 !important;
+          transition-duration: 0.01ms !important;
+        }
+      }
+
+      @media (forced-colors: active) {
+        .skip-link,
+        .hero,
+        details {
+          forced-color-adjust: auto;
+        }
+
+        summary:focus-visible {
+          outline: 2px solid Highlight;
+          outline-offset: 2px;
+          box-shadow: none;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <a class="skip-link" href="#main">Skip to main content</a>
+
+    <main id="main">
+      <section class="hero" aria-labelledby="faq-title">
+        <span class="eyebrow">Cat FAQ</span>
+        <h1 id="faq-title">Quick answers for cat curiosity</h1>
+        <p class="lede">
+          A clean, modern FAQ with collapsed questions by default. Open any
+          item to read the answer.
+        </p>
+      </section>
+
+      <section class="faq-list" aria-label="Frequently asked questions about cats">
+        <div class="example">
+          <details>
+            <summary>Why do cats purr?</summary>
+            <div class="details">
+              <p>
+                Cats often purr when they are content, but they also purr to
+                calm themselves, ask for comfort, or recover from stress.
+              </p>
+            </div>
+          </details>
+        </div>
+
+        <div class="example">
+          <details>
+            <summary>Why do cats knead with their paws?</summary>
+            <div class="details">
+              <p>
+                Kneading is a soothing behavior that starts in kittenhood. It
+                can signal comfort, affection, or excitement about a cozy spot.
+              </p>
+            </div>
+          </details>
+        </div>
+
+        <div class="example">
+          <details>
+            <summary>How much should I feed my cat?</summary>
+            <div class="details">
+              <p>
+                It depends on age, weight, activity level, and the food you use.
+                Your veterinarian or the food label can help you find the right
+                daily amount.
+              </p>
+            </div>
+          </details>
+        </div>
+
+        <div class="example">
+          <details>
+            <summary>Why do cats sleep so much?</summary>
+            <div class="details">
+              <p>
+                Cats are natural energy conservers. Long naps help them stay
+                ready for bursts of play, hunting behavior, and general cat
+                mischief.
+              </p>
+            </div>
+          </details>
+        </div>
+
+        <div class="example">
+          <details>
+            <summary>Is catnip safe for most cats?</summary>
+            <div class="details">
+              <p>
+                Yes, for most cats it is safe in moderation. Some cats are
+                highly responsive, while others barely react at all.
+              </p>
+              <p>
+                A small amount of catnip on a toy or scratcher is usually enough
+                for a fun session.
+              </p>
+            </div>
+          </details>
+        </div>
+      </section>
+
+      <p class="footer-note">
+        Tip: each question uses native disclosure controls, so it works with
+        keyboard and assistive technology out of the box.
+      </p>
+    </main>
+  </body>
+</html>
*** End Patch
